        self.sessions.edits["ui"] = ("ui.txt", "after")
        self.start()
        real, failures = automatic.git_worktree, []
        def locked(repository, *arguments):
            if arguments[-2].endswith("/review-worktree"):
                failures.append(arguments[-2])
                raise WorktreeError(128, ["git", "worktree", *arguments], "", "fatal: cannot lock ref 'HEAD': File exists")
            return real(repository, *arguments)
        outcomes = []
        with patch("workflow.automatic.git_worktree", side_effect=locked), patch("workflow.automatic.wait_handoffs"):
            for i in range(8):  # what supervise() does: a new automatic-step (single_step) per exit 75
                try:
                    outcomes.append(drive(self.runtime, single_step=True))
                except Exception as error:
                    outcomes.append(f"raised: {error}")
                    break
        reentries = [e for e in self.events() if e["node"] == "review" and e["message"].startswith("Re-entering the review")]
        print("\noutcomes:", outcomes)
        print("review-worktree failures:", len(failures), "re-entries:", len(reentries))

